(()=>{"use strict";class t{constructor(t){this.container=t,this.button=t.querySelector(".collapse-btn"),this.body=t.querySelector(".collapse-body"),this.arrow=this.button.querySelector(".arrow"),this.isOpen=!1,this.init()}init(){this.button.addEventListener("click",this.toggle.bind(this)),this.body.style.maxHeight="0px",this.body.style.overflow="hidden",this.body.style.transition="max-height 0.3s ease-in-out, opacity 0.3s ease-in-out",this.body.style.opacity="0"}toggle(){this.isOpen=!this.isOpen,this.isOpen?this.open():this.close()}open(){const t=this.body.scrollHeight;this.body.style.maxHeight=t+"px",this.body.style.opacity="1",this.arrow.style.transform="rotate(180deg)"}close(){this.body.style.maxHeight="0px",this.body.style.opacity="0",this.arrow.style.transform="rotate(0deg)"}}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".collapse-container").forEach((e,s)=>{const o=e.querySelector(".collapse-body");o.id||(o.id=`collapse${s+1}`),new t(e)})})})();